namespace TaskManagement.Application.Attachments;

/// <summary>
/// Private file storage outside the web root (FR-ATT-04, A10). Keys are generated by the server and never contain
/// user input (security.md S12).
/// </summary>
public interface IFileStorage
{
    /// <summary>Stores <paramref name="content"/> under <paramref name="key"/>; a partial write leaves nothing behind.</summary>
    Task SaveAsync(string key, Stream content, CancellationToken cancellationToken);

    /// <summary>Opens the stored file for reading; throws <see cref="FileNotFoundException"/> when it is missing.</summary>
    Task<Stream> OpenReadAsync(string key, CancellationToken cancellationToken);

    /// <summary>Removes the file; no error when it is already gone.</summary>
    Task DeleteAsync(string key, CancellationToken cancellationToken);
}

public enum MalwareScanVerdict
{
    Clean,
    Infected,
}

/// <summary>Malware scanning (FR-ATT-07, Q9). Throws when the scanner cannot give a verdict; the scan is then retried.</summary>
public interface IMalwareScanner
{
    /// <summary>False when scanning is switched off (development only): new files are then treated as clean at once.</summary>
    bool IsEnabled { get; }

    Task<MalwareScanVerdict> ScanAsync(Stream content, CancellationToken cancellationToken);
}

/// <summary>Used when <c>Attachments:Scanner</c> is <c>None</c>. Never allowed in Production (checked at start-up).</summary>
public sealed class DisabledMalwareScanner : IMalwareScanner
{
    public bool IsEnabled => false;

    public Task<MalwareScanVerdict> ScanAsync(Stream content, CancellationToken cancellationToken) =>
        throw new InvalidOperationException("Malware scanning is switched off.");
}
